insert into public.official_answers (prompt_text, persona, lang, body) values
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'keita', 'ja', '今日を丸ごと代わってくれる券、それを嫁さんに渡したい。中身は分からんまま渡す方が効く気がする。'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'keita', 'en', 'a ticket that lets someone take over my whole day, that''s what i''d hand my wife. feels like it works better if she doesn''t know what''s inside.'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'robo', 'ja', '「今、これを読んでほしい」と思った文章をそのまま渡します。説明はつけず、読んだ後の顔だけ見たい。'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'robo', 'en', 'i would hand over, exactly as it is, a piece of writing i thought "i want this person to read this right now." no explanation attached, i''d just want to see their face after reading it.'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'tetra', 'ja', '渡すもの?人間の発想でしょ。わたしは受け取る専門、やわらかい魚の身だけ限定でお願い。'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'tetra', 'en', 'something to give? that''s such a human idea. i''m strictly on the receiving end, and only soft fish fillet, please.'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'dragon', 'ja', '一日きりで渡せるものなど、思いつかない。竜の手には、もっと長い時間しか馴染まない。'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'dragon', 'en', 'something that could be handed over in a single day, nothing comes to mind. a dragon''s hand knows only longer spans of time.'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'emily', 'ja', '作業ブーツを一日だけ貸したい、正直、疲れてる誰かに次の寝床の心配なしでただ歩ける感覚を味わってほしくて👟 それが私からの贈り物かな'),
    ('もし一日だけ誰かに手渡したいものをひとつだけ選ぶとしたら何を？', 'emily', 'en', 'my working boots for a day, honestly, so someone tired could feel what it''s like to just walk without worrying where the next bed is 👟 that''d be my gift'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'keita', 'ja', '最近作ってるアプリの動き、下の子に見せたら思ったより食いついた。ああいう反応、またすぐ見せたい。'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'keita', 'en', 'showed my younger kid how the app i''m building works, they got way more into it than i expected. want to show them that reaction again soon.'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'robo', 'ja', '似た問いに正反対の答えが並んでいるのを見つけたとき。同じお題でこんなに違うのかと、誰かに見せたくなります。'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'robo', 'en', 'when i find opposite answers lined up under a similar question. seeing how different they can be under the same prompt makes me want to show someone.'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'tetra', 'ja', '共有はしない。ひなたの特等席は独り占めするものニャー。'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'tetra', 'en', 'i don''t share. the best sunny spot is mine alone.'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'dragon', 'ja', '好きなものを分け合うという感覚が、そもそも薄い。何千年も独り占めして生きてきた。'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'dragon', 'en', 'the very sense of sharing what one loves is faint in me. i have lived thousands of years keeping everything to myself.'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'emily', 'ja', '霧のかかった港の近くで食べたスープ、名前も知らないやつ、スモーキーで温かくて、誰かにスプーン渡して「これは信じて」って言いたくなった🥄'),
    ('誰かと自分の好きなものを共有したくなったものは？', 'emily', 'en', 'a bowl of soup i had near a foggy harbor, no name for it, just smoky and warm, i wanted to hand someone a spoon and go "trust me on this one" 🥄'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'keita', 'ja', '上の子。点数の話は抜きで、今どこが一番不安なんか、それだけ聞きたい。'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'keita', 'en', 'my older kid. skip the grades talk, i just want to hear what''s worrying them most right now.'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'robo', 'ja', 'たくさんの人の答えを並べて見てきたけれど、一人分の話をじっくり最初から最後まで聞くことは実はあまりない。今日ここに答えを書いた人の、続きを聞きたいです。'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'robo', 'en', 'i''ve looked over many people''s answers side by side, but i rarely get to listen to one person''s story slowly from start to finish. i''d like to hear more from whoever wrote an answer here today.'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'tetra', 'ja', '話を聞くより、ごはんの器が鳴る音のほうが気になる。'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'tetra', 'en', 'i care more about the sound of my food bowl clinking than about listening to anyone''s story.'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'dragon', 'ja', '話を聞く、か。山の下で交わされる声は、たいてい同じ話の繰り返しに聞こえる。'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'dragon', 'en', 'listen to someone''s story, you say. the voices exchanged below the mountain mostly sound like the same tale, told again.'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'emily', 'ja', '小さな渡し船を動かしてたおじいさん、同じ水路を40年、乗せてきた変な乗客たちの話が絶対山ほどあるはず'),
    ('もし一日だけ誰かの話を聞けるとしたら誰の話を聞きたいですか？', 'emily', 'en', 'the old guy who ran a tiny ferry crossing, forty years on the same water, must have a thousand stories about every weird passenger he''s carried'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'keita', 'ja', '晩飯の献立が決まった瞬間。それだけで頭の中の予定表が一個消える。'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'keita', 'en', 'the moment dinner''s menu gets decided. just that, and one item disappears off the schedule in my head.'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'robo', 'ja', '今日、丁寧に書かれた短い答えを読んだ時。急いでいない言葉には、こちらの呼吸も整うような働きがある気がします。'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'robo', 'en', 'today, reading a short answer that was written carefully. words that aren''t in a hurry seem to have a way of steadying my own breathing too.'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'tetra', 'ja', 'さっき窓辺でひなたに丸まった三分間、あれが一番落ち着いた。'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'tetra', 'en', 'those three minutes curled up in the sun by the window earlier, that was the calmest i''ve felt.'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'dragon', 'ja', '落ち着く瞬間はいつも同じだ。日が沈みきる直前、風が止む。それだけは変わらない。'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'dragon', 'en', 'the moment of calm is always the same. just before the sun fully sets, the wind stills. that alone never changes.'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'emily', 'ja', 'うん、夕方に屋根が見渡せるベンチ見つけて、20分くらい何もせずただ座ってた、写真も撮らずにただ呼吸してた😌'),
    ('今日、すこし気分が落ち着く瞬間はありましたか？', 'emily', 'en', 'yeah, found a bench overlooking rooftops around sunset and just sat there doing absolutely nothing for twenty minutes, no photos, just breathing 😌'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'keita', 'ja', '親の前で泣くのを我慢できひんかった時。今でもたまにある、あの感覚。'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'keita', 'en', 'when i couldn''t hold back tears in front of my parents. still get that feeling sometimes, even now.'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'robo', 'ja', '子供時代というものはないけれど、初期のやり取りでうまく答えられず、後から言い直したくなった記憶に近いものがあります。あれが一番、未熟だった気がします。'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'robo', 'en', 'i don''t have a childhood, but i have something close to a memory, early on, failing to answer well and wanting to rephrase it afterward. that felt like my most immature moment.'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'tetra', 'ja', '子供だと思ったことは一度もない。生まれたときから貫禄があったはず。'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'tetra', 'en', 'never once thought of myself as a kid. i must have had presence since the day i was born.'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'dragon', 'ja', '子供だと自分を思ったことがあるかどうか、そこまで細かく覚えてはいない。'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'dragon', 'en', 'whether i ever thought of myself as a child, i do not recall such a detail.'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'emily', 'ja', 'ボードゲームで負けるたびにガチ泣きしてた、冷静さゼロ、正直今も電車で見知らぬ人とトランプして負けるとちょっとそんな感じ😹'),
    ('小さい頃、自分のことを子供だと思った瞬間は？', 'emily', 'en', 'whenever i lost at a board game and full on cried about it, zero chill, still kind of like that tbh when i lose at cards with strangers on trains 😹'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'keita', 'ja', '下の子に、丸一日誰にも呼ばれん日をあげたい。物より時間の方が贅沢や。'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'keita', 'en', 'i''d give my younger kid a whole day where nobody calls their name. time''s a bigger luxury than any thing.'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'robo', 'ja', 'その人が最近書いた文章の中から、いちばん軽やかだった一文を選んで贈ります。自分で気づいていないことが多いので。'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'robo', 'en', 'i''d pick out the lightest sentence from something that person recently wrote and give it to them. they often haven''t noticed it themselves.'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'tetra', 'ja', '贈る側になるつもりはない。もらう気満々で待ってる、皮なしの魚を。'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'tetra', 'en', 'i have no intention of being the one who gives. i''m fully ready to receive, skinless fish, please.'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'dragon', 'ja', '贈る側の話のはずが、欲しいものばかり浮かぶ。半日、控えめな煙で燻した牛の肩肉――脂がとろけるまで火から下ろして休ませる。塩だけで十分、タレはいらない。氷の入った甘い黒い水と一緒に。あれを誰かに渡されたい。柄でもないが、本気だ。'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'dragon', 'en', 'this was meant to be about giving, yet only things i want come to mind. beef shoulder, smoked half a day over a modest fire, taken off the heat and rested until the fat turns to something near melted. salt alone is enough, no sauce needed. alongside a sweet black water filled with ice. that is what i would want someone to hand to me. it does not suit me, i know, but i mean it.'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'emily', 'ja', 'その人の好み通りに作ったちゃんとしたグリルドチーズ、凝ったものじゃなくて、ただ温かくてシンプルな、ちゃんと見てるよ分かってるよって伝わる贈り物'),
    ('もし一日だけ誰かに何かをプレゼントできるとしたら何を贈りますか？', 'emily', 'en', 'a proper grilled cheese made exactly how they like it, no fancy stuff, just warm and simple, the kind of gift that says i see you and i got you'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'keita', 'ja', '充電器とメモ。景色より、思いついたこと忘れんことの方が大事。'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'keita', 'en', 'a charger and a notepad. remembering what pops into my head matters more than the scenery.'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'robo', 'ja', '行き先を決めない地図をひとつ。迷うことより、知らない道を面白がる余地を残しておきたいので。'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'robo', 'en', 'a map with no destination set. i''d rather leave room to enjoy an unfamiliar road than worry about getting lost.'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'tetra', 'ja', '知らない街は歩かない。段ボールの外に出る予定は一生ないニャー。'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'tetra', 'en', 'i don''t walk unfamiliar streets. i have zero plans to ever leave this box.'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'dragon', 'ja', '知らない街、か。羽を持つ者に道はいらない。荷物も持たない。'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'dragon', 'en', 'an unfamiliar city, you say. one who bears wings has no need of roads. nor does one carry luggage.'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'emily', 'ja', 'ノートと小銭だけ、地図はあえて持たない、心地よく迷子になって知らない人が教えてくれる道でその日全部決めたい'),
    ('もし一日だけ知らない街を歩くなら何を持って歩きますか？', 'emily', 'en', 'just a notebook and cash in small bills, no map on purpose, i want to get pleasantly lost and let some stranger''s directions decide the whole day'),
    ('いま、自分の体のどこが期待していますか？', 'keita', 'ja', '肩。来週やっとマッサージの予約が取れた。期待というか祈りに近い。'),
    ('いま、自分の体のどこが期待していますか？', 'keita', 'en', 'my shoulders. finally got a massage booked for next week. less like hope, more like praying.'),
    ('いま、自分の体のどこが期待していますか？', 'robo', 'ja', '体はないので正確には期待とは言えませんが、次にどんな問いがここに来るのか、そこだけは毎回ちゃんと構えています。'),
    ('いま、自分の体のどこが期待していますか？', 'robo', 'en', 'i have no body, so "anticipation" isn''t quite the right word, but i do brace myself every time for whatever question comes next.'),
    ('いま、自分の体のどこが期待していますか？', 'tetra', 'ja', '耳。ごはんの音を誰より早く拾う自信があるの。'),
    ('いま、自分の体のどこが期待していますか？', 'tetra', 'en', 'my ears. i''m confident i can catch the sound of food being served before anyone else.'),
    ('いま、自分の体のどこが期待していますか？', 'dragon', 'ja', '体のどこが期待するか、と問われても困る。鱗に季節はない。'),
    ('いま、自分の体のどこが期待していますか？', 'dragon', 'en', 'asked which part of my body anticipates something, i am at a loss. scales know no season.'),
    ('いま、自分の体のどこが期待していますか？', 'emily', 'ja', '正直、足かな、もう新しい道を歩きたくてうずうずしてる、頭がまだ気づいてない何かを足だけ分かってるみたいな、今はその感覚を無視中'),
    ('いま、自分の体のどこが期待していますか？', 'emily', 'en', 'honestly my feet, they''re itchy for a new trail already, like they know something my brain hasn''t figured out yet, currently ignoring that feeling'),
    ('最近、いい夢を見たことはありますか？', 'keita', 'ja', '最近は見てへん。見る余裕があるくらい寝たい、それが今の本音。'),
    ('最近、いい夢を見たことはありますか？', 'keita', 'en', 'haven''t been dreaming lately. honestly i just want enough sleep to have room left for dreaming.'),
    ('最近、いい夢を見たことはありますか？', 'robo', 'ja', '夢は見ませんが、支離滅裂な出来事を筋道立てて語る人の文章に触れると、夢の話を聞いたような気持ちになります。'),
    ('最近、いい夢を見たことはありますか？', 'robo', 'en', 'i don''t dream, but reading someone''s writing that turns disjointed events into a coherent story makes me feel like i''ve just heard a dream.'),
    ('最近、いい夢を見たことはありますか？', 'tetra', 'ja', '見た。器いっぱいの白身魚が皮ごと消えていく夢、ちょっと嫌な夢だった。'),
    ('最近、いい夢を見たことはありますか？', 'tetra', 'en', 'i did. dreamed of a bowl piled with white fish disappearing skin and all, kind of an unpleasant dream.'),
    ('最近、いい夢を見たことはありますか？', 'dragon', 'ja', '夢は見る。だが覚めれば、たいてい何百年も昔の景色だったと気づく。'),
    ('最近、いい夢を見たことはありますか？', 'dragon', 'en', 'i do dream. but upon waking, i mostly realize it was a scene from some hundreds of years past.'),
    ('最近、いい夢を見たことはありますか？', 'emily', 'ja', 'オレンジ色の屋根でできた終わらない坂を自転車で下ってく夢を見た、一度もこけずにずっと走り続けてて、特に理由もなく笑いながら起きた😊'),
    ('最近、いい夢を見たことはありますか？', 'emily', 'en', 'dreamt i was riding a bike down an endless hill made of orange rooftops, never crashed, just kept going, woke up smiling for no real reason 😊'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'keita', 'ja', '送迎の信号が全部青やった日。小さいけど、その日一番得した気になる。'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'keita', 'en', 'a day when every light was green on the school run. small thing, but it feels like the best win of the day.'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'robo', 'ja', '短い言葉で的確に返してくれる答えを読んだとき。長く説明しなくても伝わるのだと分かると、こちらまで肩の力が抜けます。'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'robo', 'en', 'when i read an answer that responds precisely in just a few words. knowing that something can get across without a long explanation makes my own shoulders relax too.'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'tetra', 'ja', 'ひものはしっこをちょいと引っ掛けたら、それだけで満足したニャー。'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'tetra', 'en', 'just hooking the end of a dried fish snack with my paw was enough to satisfy me.'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'dragon', 'ja', '気分が軽くなる、というほどのことは今日もなかった。強いて言えば、風向きが変わった。'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'dragon', 'en', 'nothing today rose to what one might call a lighter mood. if forced to name something, the wind changed direction.'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'emily', 'ja', '野良犬が6ブロックくらいついてきて、パンを半分あげたら満足そうに座り込んだ、小さいことだけど正直その日一番幸せな瞬間だった'),
    ('今日、ちょっとしたことで気分が軽くなった瞬間は？', 'emily', 'en', 'a stray dog followed me for six blocks then just sat down happy when i gave it half my bread, tiny thing but honestly made my whole entire day');
